const projects={
 side:{title:'A reading list. A real first version.',context:'A personal reading list, built with Next.js and Supabase.',tags:'NEXT.JS · SUPABASE · SOLO',stack:'Next.js and Supabase',goal:'a personal reading list',steps:[['Choose the one useful flow','Save a book. Mark it read. Keep the first version small.','Define the smallest complete flow for saving a book and marking it read. Describe the screens and data involved.'],['Give your books a home','Start with books and a reading status.','Design a minimal data model for books and reading status. Provide table definitions and explain each field.'],['Build it from end to end','Make the core reading-list flow work before adding extras.','Implement the core reading-list flow: add a book, display saved books, and update reading status. Include loading, empty, and error states.'],['Put the first version in someone’s hands','Use real feedback to choose what comes next.','Create a short manual verification checklist for adding, viewing, and marking a book read. Include empty inputs and a failed save.']],skips:[['Microservices','One small app doesn’t need separate services.'],['A recommendation engine','Get the core reading list working first.'],['A feature-flag service','There are no user cohorts to manage yet.']]},
 study:{title:'A course project with a clear purpose.',context:'A student research tracker, built with React and SQLite.',tags:'REACT · SQLITE · COURSE PROJECT',stack:'React and SQLite',goal:'a student research tracker',steps:[['Start with the learning objective','Connect the project to what the course asks you to demonstrate.','Define an achievable scope for a research tracker. Connect the main features to a clear learning objective.'],['Map the records and relationships','Keep sources, notes, and project references easy to explain.','Design a minimal schema for research sources and notes. Explain the relationship between them and give example records.'],['Make the main flow demonstrable','A complete core experience is easier to evaluate.','Implement a complete flow for adding a research source and attaching a note. Include validation and readable error states.'],['Document the result and the trade-offs','Show what works, what you chose, and what you learned.','Write an outline for the project report and demo: requirements, architecture, implementation decisions, limitations, and lessons learned.']],skips:[['Subscription billing','The project isn’t selling a paid service.'],['Multi-region deployment','One demonstration environment is enough.'],['Growth analytics','The goal is learning, not acquisition.']]},
 sprint:{title:'A hackathon idea that makes the deadline.',context:'A campus event finder, built with React and a public events API.',tags:'REACT · PUBLIC API · HACKATHON',stack:'React and a public events API',goal:'a campus event finder',steps:[['Find the demo moment','Choose the one thing the audience should remember.','Define a 60-second demo for a campus event finder. Choose one complete user journey and explain what makes it useful.'],['Keep the setup familiar','Use the simplest stack that supports the experience.','Outline a minimal React app that reads from a public events API. Include a clear boundary for API fetching and a fallback when data is unavailable.'],['Build the path you’ll demonstrate','A working event search beats five half-built features.','Implement event search and event details with accessible controls. Include loading, empty, and failed-request states.'],['Rehearse it before the deadline','Have a story, a working flow, and a fallback.','Prepare a demo rehearsal checklist, a concise presentation outline, and a fallback plan if the public events API is unavailable.']],skips:[['A full design system','A small demo needs a consistent interface first.'],['A platform migration','Spend your limited time on the core experience.'],['Background job infrastructure','The demonstrated flow doesn’t need it.']]}
};
const tabs=[...document.querySelectorAll('[role=tab][data-project]')];
const steps=document.querySelector('#plan-steps');
const drawer=document.querySelector('#prompt-drawer');
const skipToggle=document.querySelector('.skip-toggle');
const skipped=document.querySelector('#skipped-steps');
let selected='side';let activePrompt=-1;
function closePrompt(){drawer.hidden=true;activePrompt=-1;document.querySelectorAll('.plan-step').forEach(step=>step.setAttribute('aria-expanded','false'));}
function renderProject(key){
 selected=key;const project=projects[key];
 tabs.forEach(tab=>{const active=tab.dataset.project===key;tab.setAttribute('aria-selected',String(active));tab.tabIndex=active?0:-1;});
 document.querySelector('#demo-content').setAttribute('aria-labelledby',`tab-${key}`);
 document.querySelector('#plan-title').textContent=project.title;
 document.querySelector('#project-context').textContent=project.context;
 document.querySelector('#project-tags').textContent=project.tags;
 steps.replaceChildren(...project.steps.map(([title,description],index)=>{
  const button=document.createElement('button');button.className='plan-step';button.setAttribute('aria-expanded','false');button.setAttribute('aria-controls','prompt-drawer');button.setAttribute('aria-label',`${title}. View coding prompt`);
  button.innerHTML=`<span>0${index+1}</span><div><h3>${title}</h3><p>${description}</p></div><span class="step-arrow">↗</span>`;
  button.addEventListener('click',()=>{const wasOpen=activePrompt===index;closePrompt();if(wasOpen)return;activePrompt=index;button.setAttribute('aria-expanded','true');document.querySelector('#step-prompt').textContent=`I’m building ${project.goal} with ${project.stack}. ${project.steps[index][2]} Keep the solution focused on this first version.`;document.querySelector('.copy-status').textContent='';drawer.hidden=false;});
  return button;
 }));
 skipped.replaceChildren(...project.skips.map(([title,reason])=>{const row=document.createElement('div');row.className='skipped-row';const label=document.createElement('s');label.textContent=title;const explanation=document.createElement('span');explanation.textContent=reason;row.append(label,explanation);return row;}));
 document.querySelector('#skip-count').textContent=project.skips.length;skipped.hidden=true;skipToggle.setAttribute('aria-expanded','false');document.querySelector('.toggle-icon').textContent='+';closePrompt();
}
tabs.forEach((tab,index)=>{tab.addEventListener('click',()=>renderProject(tab.dataset.project));tab.addEventListener('keydown',event=>{let next=index;if(['ArrowRight','ArrowDown'].includes(event.key))next=(index+1)%tabs.length;else if(['ArrowLeft','ArrowUp'].includes(event.key))next=(index+tabs.length-1)%tabs.length;else if(event.key==='Home')next=0;else if(event.key==='End')next=tabs.length-1;else return;event.preventDefault();renderProject(tabs[next].dataset.project);tabs[next].focus();});});
skipToggle.addEventListener('click',()=>{const open=skipToggle.getAttribute('aria-expanded')!=='true';skipped.hidden=!open;skipToggle.setAttribute('aria-expanded',String(open));document.querySelector('.toggle-icon').textContent=open?'−':'+';});
document.querySelector('.close-drawer').addEventListener('click',()=>{const trigger=document.querySelector('.plan-step[aria-expanded=true]');closePrompt();trigger?.focus();});
document.querySelector('.copy-button').addEventListener('click',async()=>{const status=document.querySelector('.copy-status');try{await navigator.clipboard.writeText(document.querySelector('#step-prompt').textContent);status.textContent='Copied. Ready for your coding agent.';}catch{status.textContent='Select the prompt above to copy it manually.';}});
const menu=document.querySelector('.menu-button');const nav=document.querySelector('#nav-links');
function closeMenu(){nav.classList.remove('open');menu.setAttribute('aria-expanded','false');menu.setAttribute('aria-label','Open navigation');}
menu.addEventListener('click',()=>{const open=menu.getAttribute('aria-expanded')!=='true';nav.classList.toggle('open',open);menu.setAttribute('aria-expanded',String(open));menu.setAttribute('aria-label',open?'Close navigation':'Open navigation');});
nav.querySelectorAll('a').forEach(link=>link.addEventListener('click',closeMenu));
document.addEventListener('keydown',event=>{if(event.key==='Escape'){closeMenu();if(!drawer.hidden){const trigger=document.querySelector('.plan-step[aria-expanded=true]');closePrompt();trigger?.focus();}}});
const reduced=matchMedia('(prefers-reduced-motion: reduce)');const motionButton=document.querySelector('.motion-button');let userPaused=false;let phase=0;let timer=null;let heroVisible=true;
const activities=['Understanding your context','Finding the useful next step','Leaving out the detours','Preparing your coding prompt'];
function syncMotion(){const paused=userPaused||reduced.matches;document.body.classList.toggle('page-hidden',document.hidden);const cardsButton=document.querySelector('.cards-motion-button');cardsButton.setAttribute('aria-pressed',String(userPaused));cardsButton.textContent=userPaused?'▷ Resume animations':'Ⅱ Pause animations';document.body.classList.toggle('motion-paused',paused);motionButton.setAttribute('aria-pressed',String(userPaused));motionButton.innerHTML=userPaused?'<span>▷</span> Resume motion':'<span>Ⅱ</span> Pause motion';clearInterval(timer);timer=null;if(!paused&&!document.hidden&&heroVisible){timer=setInterval(()=>{phase=(phase+1)%activities.length;document.querySelector('#core-activity').textContent=activities[phase];document.querySelectorAll('.thinking-list li').forEach((item,index)=>item.classList.toggle('active',index===phase));},2600);}}
motionButton.addEventListener('click',()=>{userPaused=!userPaused;syncMotion();});reduced.addEventListener('change',syncMotion);document.addEventListener('visibilitychange',syncMotion);
const heroObserver=new IntersectionObserver(entries=>{heroVisible=entries[0].isIntersecting;syncMotion();});heroObserver.observe(document.querySelector('.hero'));
const revealObserver=new IntersectionObserver(entries=>entries.forEach(entry=>{if(entry.isIntersecting){entry.target.classList.add('visible');revealObserver.unobserve(entry.target);}}),{threshold:.07});
document.querySelectorAll('.section-heading,.center-heading,.journey-grid article,.world-layout,.feature-card,.manifesto,.faq-section>div,.closing-content>div').forEach(element=>{element.classList.add('reveal');revealObserver.observe(element);});document.body.classList.add('motion-ready');
let queued=false;function updateProgress(){const range=document.documentElement.scrollHeight-innerHeight;document.querySelector('.scroll-progress').style.width=`${range>0?Math.max(0,Math.min(1,scrollY/range))*100:0}%`;queued=false;}
addEventListener('scroll',()=>{if(!queued){queued=true;requestAnimationFrame(updateProgress);}},{passive:true});addEventListener('resize',updateProgress);
document.querySelector('#year').textContent=new Date().getFullYear();renderProject('side');syncMotion();updateProgress();

// Decorative diagrams run only while visible and share the page motion preference.
document.querySelector('.cards-motion-button').addEventListener('click',()=>{userPaused=!userPaused;syncMotion();});
const cardMotionObserver=new IntersectionObserver(entries=>entries.forEach(entry=>entry.target.classList.toggle('motion-in-view',entry.isIntersecting)),{threshold:.1});
document.querySelectorAll('.animated-features .feature-art').forEach(art=>cardMotionObserver.observe(art));
